--
-- Table structure for table `bills`
--

DROP TABLE IF EXISTS `bills`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `bills` (
  `id` varchar(191) COLLATE utf8mb4_unicode_ci NOT NULL,
  `sessionId` varchar(191) COLLATE utf8mb4_unicode_ci NOT NULL,
  `restaurantId` varchar(191) COLLATE utf8mb4_unicode_ci NOT NULL,
  `billNumber` varchar(6) COLLATE utf8mb4_unicode_ci NOT NULL,
  `status` enum('DRAFT','FINAL','PAID','VOIDED') COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'DRAFT',
  `subtotal` decimal(10,2) NOT NULL,
  `taxRate` decimal(5,2) NOT NULL,
  `taxAmount` decimal(10,2) NOT NULL,
  `discountAmount` decimal(10,2) NOT NULL DEFAULT '0.00',
  `totalAmount` decimal(10,2) NOT NULL,
  `notes` text COLLATE utf8mb4_unicode_ci,
  `generatedById` varchar(191) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `paidAt` datetime(3) DEFAULT NULL,
  `createdAt` datetime(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
  `updatedAt` datetime(3) NOT NULL,
  `customerId` varchar(191) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `SpecialPriceApplied` tinyint(1) NOT NULL DEFAULT '0',
  `priceruleId` varchar(191) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `customerEmail` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `customerName` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `customerPhone` varchar(30) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `couponId` varchar(191) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `coupounDiscountAmount` decimal(10,2) NOT NULL DEFAULT '0.00',
  `loyalityPointDiscountAmount` decimal(10,2) NOT NULL DEFAULT '0.00',
  `loyalityPointRedemptionId` varchar(191) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `grossAmount` decimal(10,2) NOT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `bills_sessionId_key` (`sessionId`),
  UNIQUE KEY `bills_restaurantId_billNumber_key` (`restaurantId`,`billNumber`),
  KEY `bills_restaurantId_idx` (`restaurantId`),
  KEY `bills_status_idx` (`status`),
  KEY `bills_generatedById_fkey` (`generatedById`),
  KEY `bills_customerId_fkey` (`customerId`),
  KEY `bills_priceruleId_fkey` (`priceruleId`),
  KEY `bills_loyalityPointRedemptionId_fkey` (`loyalityPointRedemptionId`),
  KEY `bills_couponId_fkey` (`couponId`),
  CONSTRAINT `bills_couponId_fkey` FOREIGN KEY (`couponId`) REFERENCES `coupons` (`id`) ON DELETE SET NULL ON UPDATE CASCADE,
  CONSTRAINT `bills_customerId_fkey` FOREIGN KEY (`customerId`) REFERENCES `customers` (`id`) ON DELETE SET NULL ON UPDATE CASCADE,
  CONSTRAINT `bills_generatedById_fkey` FOREIGN KEY (`generatedById`) REFERENCES `users` (`id`) ON DELETE SET NULL ON UPDATE CASCADE,
  CONSTRAINT `bills_loyalityPointRedemptionId_fkey` FOREIGN KEY (`loyalityPointRedemptionId`) REFERENCES `loyality_point_redemptions` (`id`) ON DELETE SET NULL ON UPDATE CASCADE,
  CONSTRAINT `bills_priceruleId_fkey` FOREIGN KEY (`priceruleId`) REFERENCES `price_rules` (`id`) ON DELETE SET NULL ON UPDATE CASCADE,
  CONSTRAINT `bills_restaurantId_fkey` FOREIGN KEY (`restaurantId`) REFERENCES `restaurants` (`id`) ON DELETE CASCADE ON UPDATE CASCADE,
  CONSTRAINT `bills_sessionId_fkey` FOREIGN KEY (`sessionId`) REFERENCES `order_sessions` (`id`) ON DELETE CASCADE ON UPDATE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

