/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `vendor_payments` (
  `id` varchar(191) COLLATE utf8mb4_unicode_ci NOT NULL,
  `vendorId` varchar(191) COLLATE utf8mb4_unicode_ci NOT NULL,
  `restaurantId` varchar(191) COLLATE utf8mb4_unicode_ci NOT NULL,
  `paidAmount` decimal(10,2) NOT NULL DEFAULT '0.00',
  `dueAmount` decimal(10,2) NOT NULL,
  `status` enum('PENDING','PAID') COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'PENDING',
  `type` enum('INVOICE','ADVANCE','PARTIAL') COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'INVOICE',
  `paymentMethod` enum('CASH','CARD','UPI','ONLINE','OTHER') COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `referenceNo` varchar(100) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `notes` text COLLATE utf8mb4_unicode_ci,
  `paidAt` datetime(3) DEFAULT NULL,
  `createdById` varchar(191) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `createdAt` datetime(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
  `updatedAt` datetime(3) NOT NULL,
  PRIMARY KEY (`id`),
  KEY `vendor_payments_vendorId_idx` (`vendorId`),
  KEY `vendor_payments_restaurantId_idx` (`restaurantId`),
